@IsTest
private class OwnedHeaderJSONObservation {
    public class PlainHeader {
        public String entityName;
        public String changeType;
        public String changeOrigin;
        public String transactionKey;
        public Integer sequenceNumber;
        public Long commitTimestamp;
        public String commitUser;
        public Long commitNumber;
        public List<String> recordIds;
        public List<String> changedFields;
        public List<String> nulledFields;
        public List<String> diffFields;
    }
    private static String populated() {
        return JSON.serialize(new Map<String,Object>{
            'entityName'=>'Account','changeType'=>'UPDATE','changeOrigin'=>'owned',
            'transactionKey'=>'owned-tx','sequenceNumber'=>7,'commitTimestamp'=>1700000000123L,
            'commitUser'=>'005000000000001AAA','commitNumber'=>42L,
            'recordIds'=>new List<String>{'001000000000001AAA','001000000000002AAA'},
            'changedFields'=>new List<String>{'Name'},'nulledFields'=>new List<String>{'Industry'},
            'diffFields'=>new List<String>{'Description'}
        });
    }
    private static List<Object> fields(EventBus.ChangeEventHeader header) {
        if(header==null) return new List<Object>{'null'};
        return new List<Object>{'value',header.entityName,header.changeType,header.changeOrigin,
            header.transactionKey,header.sequenceNumber,header.commitTimestamp,header.commitUser,
            header.commitNumber,header.recordIds,header.changedFields,header.nulledFields,header.diffFields};
    }
    private static void observeHeader(String input,Boolean strict) {
        Object observed;
        try {
            EventBus.ChangeEventHeader header=(EventBus.ChangeEventHeader)(strict
                ?JSON.deserializeStrict(input,EventBus.ChangeEventHeader.class)
                :JSON.deserialize(input,EventBus.ChangeEventHeader.class));
            observed=fields(header);
        } catch(Exception issue) {
            observed=new List<Object>{'exception',issue.getTypeName(),issue.getMessage()};
        }
        emit(observed);
    }
    private static void emit(Object observed) {
        System.assert(false,'HEADER_JSON_OBSERVATION|'+JSON.serialize(observed));
    }
    @IsTest static void populatedHeader() {observeHeader(populated(),false);}
    @IsTest static void emptyHeader() {observeHeader('{}',false);}
    @IsTest static void nullHeader() {observeHeader('null',false);}
    @IsTest static void plainDTOControl() {
        Object observed;
        try {
            PlainHeader header=(PlainHeader)JSON.deserialize(populated(),PlainHeader.class);
            observed=new List<Object>{'value',header.entityName,header.changeType,header.changeOrigin,
                header.transactionKey,header.sequenceNumber,header.commitTimestamp,header.commitUser,
                header.commitNumber,header.recordIds,header.changedFields,header.nulledFields,header.diffFields};
        } catch(Exception issue) {
            observed=new List<Object>{'exception',issue.getTypeName(),issue.getMessage()};
        }
        emit(observed);
    }
    @IsTest static void saveResultControl() {
        Object observed;
        try {
            Database.SaveResult result=(Database.SaveResult)JSON.deserialize(
                '{"success":true,"id":"001000000000001AAA","errors":[]}',Database.SaveResult.class);
            observed=new List<Object>{'value',result.isSuccess(),result.getId(),result.getErrors().size()};
        } catch(Exception issue) {
            observed=new List<Object>{'exception',issue.getTypeName(),issue.getMessage()};
        }
        emit(observed);
    }
    @IsTest static void strictUnknownHeader() {observeHeader('{"ownedUnknownProperty":1}',true);}
}

