    'nullFieldsHeader'=>'{"entityName":null,"sequenceNumber":null,"commitTimestamp":null,"recordIds":null}'
};
for(String cell:new List<String>{'populatedHeader','emptyHeader','nullHeader','strictUnknownHeader','unknownHeader','nullFieldsHeader'}) {
    Object observed;
    try {
        EventBus.ChangeEventHeader header=(EventBus.ChangeEventHeader)(cell=='strictUnknownHeader'
            ?JSON.deserializeStrict(inputs.get(cell),EventBus.ChangeEventHeader.class)
            :JSON.deserialize(inputs.get(cell),EventBus.ChangeEventHeader.class));
        if(header==null) observed=new List<Object>{'null'};
        else observed=new List<Object>{'value',header.entityName,header.changeType,header.changeOrigin,
            header.transactionKey,header.sequenceNumber,header.commitTimestamp,header.commitUser,
            header.commitNumber,header.recordIds,header.changedFields,header.nulledFields,header.diffFields};
    } catch(Exception issue) {
        observed=new List<Object>{'exception',issue.getTypeName(),issue.getMessage()};
    }
    System.debug('HEADER_JSON_ANONYMOUS|'+JSON.serialize(new Map<String,Object>{'cell'=>cell,'observed'=>observed}));
}

